/**
 * mech — Phase B gate tests.
 * Run: `bun test ./.morphmap/mech/`
 *
 * Proves the gates actually block bad submissions/approvals and pass good
 * ones — the "done = proof" enforcement. Each gate's pass/fail/skip edge,
 * the chains' short-circuit + warn-accumulate behaviour, QA-tier
 * conditionals, tool-absent skips, and the full submit_leaf/approve_leaf
 * flows wired through transitionLeaf (Phase A + B integration).
 */

import { test, expect, describe } from "bun:test";
import {
  agentSpecLifecycle,
  allGateNames,
  allLeavesComplete,
  bombadilPassed,
  boundariesClean,
  crossLeafConflictsResolved,
  crossLeafNoConflict,
  dependenciesResolvable,
  emptyEvidence,
  filesMatchSpec,
  gatesForLeafTransition,
  GATE_CHAINS,
  healthCheckPassed,
  integrationHealthCheckPassed,
  integrationReviewExists,
  leafMachine,
  lonkeroPassed,
  modelAssigned,
  npmTestAndBuild,
  p0CountZero,
  p1CountZeroIfFull,
  preSpawnGates,
  qualityReviewExists,
  reviewGates,
  runIntegrationGates,
  specEstLOC,
  specFileCount,
  specFileExists,
  specScenarioCount,
  submitGates,
  tddGuardPassed,
  toolsAssigned,
  transitionLeaf,
  type BranchState,
  type DependencyGraph,
  type IntegrationGateCtx,
  type Leaf,
  type LeafStatus,
  type TransitionGateCtx,
} from "./index";

// ── fixtures ──────────────────────────────────────────────────
function ev(over: Partial<ReturnType<typeof emptyEvidence>> = {}) {
  return { ...emptyEvidence(), ...over };
}
function leaf(over: Partial<Leaf> = {}): Leaf {
  return {
    id: "x",
    status: "pending",
    bottleneck: "standard",
    qa: "review",
    test: ["unit"],
    model: { provider: "deepseek", model: "deepseek-v4-flash", thinking: "off" },
    tools: ["agent-spec"],
    evidence: emptyEvidence(),
    reviewRounds: 0,
    trace: "b/x",
    ...over,
  };
}
function ctx(over: Partial<TransitionGateCtx> = {}): TransitionGateCtx {
  return { leaf: leaf(), evidence: emptyEvidence(), to: "in_progress", ...over };
}
function branch(leaves: Leaf[] = [], over: Partial<BranchState> = {}): BranchState {
  const lm: Record<string, Leaf> = {};
  for (const l of leaves) lm[l.id] = l;
  return {
    branchId: "b",
    status: "in_progress",
    quality: "fast",
    leaves: lm,
    subBranches: [],
    childBranchStatus: {},
    transitions: [],
    integrationStatus: {
      reviewFileExists: false,
      healthCheckPassed: null,
      bombadilPassed: null,
      lonkeroPassed: null,
      allLeavesComplete: false,
      crossLeafConflicts: [],
    },
    ...over,
  };
}
function intCtx(over: Partial<IntegrationGateCtx> = {}): IntegrationGateCtx {
  return {
    branch: branch(),
    graph: { nodes: [], edges: [] },
    rollup: { allComplete: false, anyBlocked: false, inProgress: [] },
    ...over,
  };
}

// ── pre-spawn gates ───────────────────────────────────────────
describe("pre-spawn gates", () => {
  test("specFileExists: missing→fail, present→pass", () => {
    expect(specFileExists.run(ctx({ evidence: ev({ specExists: false }) })).pass).toBe(false);
    expect(specFileExists.run(ctx({ evidence: ev({ specExists: true }) })).pass).toBe(true);
  });

  test("specScenarioCount: 5→pass, 6→fail", () => {
    expect(specScenarioCount.run(ctx({ evidence: ev({ specScenarioCount: 5 }) })).pass).toBe(true);
    const r = specScenarioCount.run(ctx({ evidence: ev({ specScenarioCount: 6 }) }));
    expect(r.pass).toBe(false);
    expect(r.reason).toMatch(/6/);
  });

  test("specFileCount: 3→pass, 4→fail", () => {
    expect(specFileCount.run(ctx({ evidence: ev({ specFileCount: 3 }) })).pass).toBe(true);
    expect(specFileCount.run(ctx({ evidence: ev({ specFileCount: 4 }) })).pass).toBe(false);
  });

  test("specEstLOC is SOFT: 250 LOC warns, never blocks a chain", () => {
    const r = specEstLOC.run(ctx({ leaf: leaf({ estLoc: 250 }), evidence: ev() }));
    expect(r.pass).toBe(false);
    expect(r.severity).toBe("warn");
    // a warn-only gate must not block the full pre-spawn chain
    const chain = preSpawnGates.map((g) => g);
    const allReasons = chain
      .map((g) => g.run(ctx({ leaf: leaf({ estLoc: 250 }), evidence: ev({ specExists: true, specScenarioCount: 2, specFileCount: 1 }) })))
      .filter((x) => !x.pass && x.severity === "block");
    expect(allReasons).toHaveLength(0);
  });

  test("specEstLOC: [est-loc] override respected, default = scenarios × 30", () => {
    expect(specEstLOC.run(ctx({ leaf: leaf({ estLoc: 150 }) })).pass).toBe(true);
    // 7 scenarios × 30 = 210 → warn
    expect(specEstLOC.run(ctx({ evidence: ev({ specScenarioCount: 7 }) })).severity).toBe("warn");
  });

  test("modelAssigned: empty model→fail", () => {
    expect(modelAssigned.run(ctx({ leaf: leaf({ model: { provider: "", model: "", thinking: "off" } }) })).pass).toBe(false);
    expect(modelAssigned.run(ctx()).pass).toBe(true);
  });

  test("toolsAssigned: empty→fail", () => {
    expect(toolsAssigned.run(ctx({ leaf: leaf({ tools: [] }) })).pass).toBe(false);
    expect(toolsAssigned.run(ctx()).pass).toBe(true);
  });

  test("dependenciesResolvable: blocked→fail, resolved→pass, no graph→skip(pass)", () => {
    const graph: DependencyGraph = { nodes: ["x", "y"], edges: [{ from: "x", to: "y", kind: "needs" }] };
    expect(
      dependenciesResolvable.run(ctx({ leaf: leaf({ id: "x" }), graph, allLeaves: { x: leaf({ id: "x" }), y: leaf({ id: "y", status: "pending" }) } })).pass,
    ).toBe(false);
    expect(
      dependenciesResolvable.run(ctx({ leaf: leaf({ id: "x" }), graph, allLeaves: { x: leaf({ id: "x" }), y: leaf({ id: "y", status: "done" }) } })).pass,
    ).toBe(true);
    expect(dependenciesResolvable.run(ctx()).pass).toBe(true); // no graph → skip
  });

  test("preSpawnGates chain: bad leaf fails at first block", () => {
    // spec missing → first gate blocks
    const results = preSpawnGates.map((g) => g.run(ctx({ evidence: ev({ specExists: false }) })));
    expect(results[0].pass).toBe(false);
  });
});

// ── submit gates ──────────────────────────────────────────────
describe("submit gates", () => {
  test("agentSpecLifecycle: false→fail, true→pass", () => {
    expect(agentSpecLifecycle.run(ctx({ evidence: ev({ agentSpecPassed: false }) })).pass).toBe(false);
    expect(agentSpecLifecycle.run(ctx({ evidence: ev({ agentSpecPassed: true }) })).pass).toBe(true);
  });

  test("tddGuardPassed: null→skip(pass), true→pass, false→fail", () => {
    expect(tddGuardPassed.run(ctx({ evidence: ev({ tddGuardPassed: null }) })).pass).toBe(true);
    expect(tddGuardPassed.run(ctx({ evidence: ev({ tddGuardPassed: true }) })).pass).toBe(true);
    expect(tddGuardPassed.run(ctx({ evidence: ev({ tddGuardPassed: false }) })).pass).toBe(false);
  });

  test("npmTestAndBuild: reports which failed", () => {
    expect(npmTestAndBuild.run(ctx({ evidence: ev({ npmTestPassed: true, npmBuildPassed: true }) })).pass).toBe(true);
    const r = npmTestAndBuild.run(ctx({ evidence: ev({ npmTestPassed: false, npmBuildPassed: true }) }));
    expect(r.pass).toBe(false);
    expect(r.reason).toContain("npm test");
    expect(r.reason).not.toContain("npm build");
  });

  test("boundariesClean: false→fail", () => {
    expect(boundariesClean.run(ctx({ evidence: ev({ boundariesClean: false }) })).pass).toBe(false);
  });

  test("crossLeafNoConflict: overlap→fail, no siblings→pass, no data→skip", () => {
    const me = leaf({ id: "a" });
    const meEv = ev({ filesChanged: ["src/x.ts"] });
    const sib = leaf({ id: "b", evidence: ev({ filesChanged: ["src/x.ts"] }) });
    expect(crossLeafNoConflict.run(ctx({ leaf: me, evidence: meEv, allLeaves: { a: me, b: sib } })).pass).toBe(false);
    const sib2 = leaf({ id: "b", evidence: ev({ filesChanged: ["src/y.ts"] }) });
    expect(crossLeafNoConflict.run(ctx({ leaf: me, evidence: meEv, allLeaves: { a: me, b: sib2 } })).pass).toBe(true);
    expect(crossLeafNoConflict.run(ctx({ leaf: me, evidence: meEv })).pass).toBe(true); // no allLeaves
  });

  test("filesMatchSpec: stray→fail, bounded→pass, no spec→skip", () => {
    const e = ev({ filesChanged: ["src/a.ts", "src/b.ts"] });
    expect(filesMatchSpec.run(ctx({ evidence: e, allowedChanges: ["src/a.ts"] })).pass).toBe(false);
    expect(filesMatchSpec.run(ctx({ evidence: e, allowedChanges: ["src/a.ts", "src/b.ts"] })).pass).toBe(true);
    expect(filesMatchSpec.run(ctx({ evidence: e })).pass).toBe(true); // no allowedChanges
  });

  test("submitGates chain: complete-good evidence passes", () => {
    const good = ev({
      agentSpecPassed: true, tddGuardPassed: true,
      npmTestPassed: true, npmBuildPassed: true, boundariesClean: true,
      filesChanged: ["src/a.ts"],
    });
    const results = submitGates.map((g) => g.run(ctx({ evidence: good, allowedChanges: ["src/a.ts"] })));
    expect(results.every((r) => r.pass)).toBe(true);
  });
});

// ── review gates ──────────────────────────────────────────────
describe("review gates", () => {
  test("qualityReviewExists: false→fail", () => {
    expect(qualityReviewExists.run(ctx({ evidence: ev({ qualityReviewExists: false }) })).pass).toBe(false);
    expect(qualityReviewExists.run(ctx({ evidence: ev({ qualityReviewExists: true }) })).pass).toBe(true);
  });

  test("p0CountZero: 0→pass, >0→fail", () => {
    expect(p0CountZero.run(ctx({ evidence: ev({ qualityReviewP0Count: 0 }) })).pass).toBe(true);
    expect(p0CountZero.run(ctx({ evidence: ev({ qualityReviewP0Count: 2 }) })).pass).toBe(false);
  });

  test("p1CountZeroIfFull: enforced at full/strict, skipped at review/none", () => {
    const e = ev({ qualityReviewP1Count: 1 });
    expect(p1CountZeroIfFull.run(ctx({ leaf: leaf({ qa: "full" }), evidence: e })).pass).toBe(false);
    expect(p1CountZeroIfFull.run(ctx({ leaf: leaf({ qa: "strict" }), evidence: e })).pass).toBe(false);
    expect(p1CountZeroIfFull.run(ctx({ leaf: leaf({ qa: "review" }), evidence: e })).pass).toBe(true);
    expect(p1CountZeroIfFull.run(ctx({ leaf: leaf({ qa: "none" }), evidence: e })).pass).toBe(true);
  });

  test("optional-result gates skip on null, fail on false, pass on true", () => {
    for (const g of [healthCheckPassed, bombadilPassed, lonkeroPassed]) {
      expect(g.run(ctx({ evidence: ev({ [g.name]: null }) })).pass).toBe(true);
      expect(g.run(ctx({ evidence: ev({ [g.name]: false }) })).pass).toBe(false);
      expect(g.run(ctx({ evidence: ev({ [g.name]: true }) })).pass).toBe(true);
    }
  });

  test("reviewGates chain: clean full-qa leaf passes", () => {
    const good = ev({
      qualityReviewExists: true, qualityReviewP0Count: 0, qualityReviewP1Count: 0,
      healthCheckPassed: true, bombadilPassed: true, lonkeroPassed: true,
    });
    const results = reviewGates.map((g) => g.run(ctx({ leaf: leaf({ qa: "full" }), evidence: good })));
    expect(results.every((r) => r.pass)).toBe(true);
  });
});

// ── integration gates ─────────────────────────────────────────
describe("integration gates", () => {
  test("allLeavesComplete: all done→pass, one not-done→fail", () => {
    const b = branch([leaf({ id: "a", status: "done" }), leaf({ id: "b", status: "done" })]);
    expect(allLeavesComplete.run(intCtx({ branch: b })).pass).toBe(true);
    // submitted is no longer enough — branch-done requires leaf-done
    const b2 = branch([leaf({ id: "a", status: "done" }), leaf({ id: "b", status: "submitted" })]);
    expect(allLeavesComplete.run(intCtx({ branch: b2 })).pass).toBe(false);
    const b3 = branch([leaf({ id: "a", status: "done" }), leaf({ id: "b", status: "in_progress" })]);
    expect(allLeavesComplete.run(intCtx({ branch: b3 })).pass).toBe(false);
  });

  test("allLeavesComplete: sub-branches incomplete→fail, complete→pass", () => {
    const b = branch([], { subBranches: ["c"] });
    expect(allLeavesComplete.run(intCtx({ branch: b, rollup: { allComplete: false, anyBlocked: false, inProgress: ["c"] } })).pass).toBe(false);
    expect(allLeavesComplete.run(intCtx({ branch: b, rollup: { allComplete: true, anyBlocked: false, inProgress: [] } })).pass).toBe(true);
  });

  test("crossLeafConflictsResolved", () => {
    expect(crossLeafConflictsResolved.run(intCtx()).pass).toBe(true);
    const b = branch([], { integrationStatus: { ...branch().integrationStatus, crossLeafConflicts: ["a↔b"] } });
    expect(crossLeafConflictsResolved.run(intCtx({ branch: b })).pass).toBe(false);
  });

  test("integrationReviewExists", () => {
    expect(integrationReviewExists.run(intCtx()).pass).toBe(false);
    const b = branch([], { integrationStatus: { ...branch().integrationStatus, reviewFileExists: true } });
    expect(integrationReviewExists.run(intCtx({ branch: b })).pass).toBe(true);
  });

  test("integrationHealthCheckPassed: null→skip, false→fail", () => {
    expect(integrationHealthCheckPassed.run(intCtx()).pass).toBe(true);
    const b = branch([], { integrationStatus: { ...branch().integrationStatus, healthCheckPassed: false } });
    expect(integrationHealthCheckPassed.run(intCtx({ branch: b })).pass).toBe(false);
  });

  test("runIntegrationGates: all good→pass, first block short-circuits", () => {
    const good = branch([leaf({ id: "a", status: "done" })], {
      integrationStatus: { reviewFileExists: true, healthCheckPassed: true, bombadilPassed: null, lonkeroPassed: null, allLeavesComplete: true, crossLeafConflicts: [] },
    });
    expect(runIntegrationGates(intCtx({ branch: good, rollup: { allComplete: true, anyBlocked: false, inProgress: [] } })).pass).toBe(true);

    const bad = branch([leaf({ id: "a", status: "in_progress" })]);
    const r = runIntegrationGates(intCtx({ branch: bad }));
    expect(r.pass).toBe(false);
    expect(r.reason).toContain("allLeavesComplete");
  });
});

// ── lattice ───────────────────────────────────────────────────
describe("lattice (transition → gate chain)", () => {
  test("pre-spawn chain on pending→in_progress", () => {
    expect(gatesForLeafTransition("pending", "in_progress")).toBe(GATE_CHAINS.preSpawn);
  });
  test("submit chain on in_progress→submitted", () => {
    expect(gatesForLeafTransition("in_progress", "submitted")).toBe(GATE_CHAINS.submit);
  });
  test("review chain on in_review→done", () => {
    expect(gatesForLeafTransition("in_review", "done")).toBe(GATE_CHAINS.review);
  });
  test("no gates on process transitions (block/unblock/revision/escape)", () => {
    expect(gatesForLeafTransition("in_progress", "blocked")).toHaveLength(0);
    expect(gatesForLeafTransition("blocked", "in_progress")).toHaveLength(0);
    expect(gatesForLeafTransition("in_review", "in_progress")).toHaveLength(0);
    expect(gatesForLeafTransition("done", "pending")).toHaveLength(0);
    expect(gatesForLeafTransition("submitted", "in_review")).toHaveLength(0);
  });
  test("allGateNames is non-empty + unique", () => {
    const names = allGateNames();
    expect(new Set(names).size).toBe(names.length);
    expect(names).toContain("specFileExists");
    expect(names).toContain("agentSpecLifecycle");
    expect(names).toContain("P0Count=0");
  });
});

// ── Phase A + B integration: full submit_leaf / approve_leaf ──
describe("full lifecycle via transitionLeaf + gates", () => {
  test("submit_leaf blocked when tests not run", () => {
    let b = branch([leaf({ id: "a", status: "in_progress" })]);
    const out = transitionLeaf(b, {
      leafId: "a",
      to: "submitted",
      gates: submitGates,
      evidence: ev({ agentSpecPassed: true, npmTestPassed: false, npmBuildPassed: true, boundariesClean: true }),
    });
    expect(out.transitioned).toBe(false);
    expect(out.result.pass).toBe(false);
    expect(out.result.reason).toContain("npmTestAndBuild");
    expect(b.leaves["a"].status).toBe("in_progress"); // unchanged
  });

  test("submit_leaf accepted with complete evidence", () => {
    const b = branch([leaf({ id: "a", status: "in_progress" })]);
    const out = transitionLeaf(b, {
      leafId: "a",
      to: "submitted",
      gates: submitGates,
      evidence: ev({
        agentSpecPassed: true, tddGuardPassed: true,
        npmTestPassed: true, npmBuildPassed: true, boundariesClean: true,
        filesChanged: ["src/a.ts"],
      }),
      allowedChanges: ["src/a.ts"],
    });
    expect(out.transitioned).toBe(true);
    expect(out.state.leaves["a"].status).toBe("submitted");
  });

  test("submit_leaf blocked on cross-leaf file conflict", () => {
    const b = branch([
      leaf({ id: "a", status: "in_progress", evidence: ev() }),
      leaf({ id: "b", status: "done", evidence: ev({ filesChanged: ["src/shared.ts"] }) }),
    ]);
    const out = transitionLeaf(b, {
      leafId: "a",
      to: "submitted",
      gates: submitGates,
      evidence: ev({
        agentSpecPassed: true, tddGuardPassed: true,
        npmTestPassed: true, npmBuildPassed: true, boundariesClean: true,
        filesChanged: ["src/shared.ts"],
      }),
      allLeaves: b.leaves,
    });
    expect(out.transitioned).toBe(false);
    expect(out.result.reason).toContain("crossLeafNoConflict");
  });

  test("approve_leaf (in_review→done) with reviewGates", () => {
    const b = branch([leaf({ id: "a", status: "in_review", qa: "full" })]);
    const out = transitionLeaf(b, {
      leafId: "a",
      to: "done",
      gates: reviewGates,
      evidence: ev({
        qualityReviewExists: true, qualityReviewP0Count: 0, qualityReviewP1Count: 0,
        healthCheckPassed: true, bombadilPassed: true, lonkeroPassed: true,
      }),
    });
    expect(out.transitioned).toBe(true);
    expect(out.state.leaves["a"].status).toBe("done");
  });

  test("approve_leaf blocked on P1 at qa:full", () => {
    const b = branch([leaf({ id: "a", status: "in_review", qa: "full" })]);
    const out = transitionLeaf(b, {
      leafId: "a",
      to: "done",
      gates: reviewGates,
      evidence: ev({ qualityReviewExists: true, qualityReviewP0Count: 0, qualityReviewP1Count: 2 }),
    });
    expect(out.transitioned).toBe(false);
    expect(out.result.reason).toContain("P1Count=0");
  });

  test("approve_leaf passes P1 at qa:review (tier-conditional skip)", () => {
    const b = branch([leaf({ id: "a", status: "in_review", qa: "review" })]);
    const out = transitionLeaf(b, {
      leafId: "a",
      to: "done",
      gates: reviewGates,
      evidence: ev({ qualityReviewExists: true, qualityReviewP0Count: 0, qualityReviewP1Count: 5 }),
    });
    expect(out.transitioned).toBe(true);
  });

  test("spawn (pending→in_progress) blocked when spec missing (pre-spawn via transitionLeaf)", () => {
    const b = branch([leaf({ id: "a", status: "pending" })]);
    const out = transitionLeaf(b, {
      leafId: "a",
      to: "in_progress",
      gates: gatesForLeafTransition("pending", "in_progress"),
      evidence: ev({ specExists: false }),
    });
    expect(out.transitioned).toBe(false);
    expect(out.result.reason).toContain("specFileExists");
  });
});

text:
/**
 * mech — Phase A core tests.
 * Run: `bun test .morphmap/mech/`
 *
 * Covers: transition legality, idempotency (crash-recovery), gate
 * short-circuit, immutable updates, dependency resolution
 * (needs vs needs-contract, build vs integrate), child-state rollup,
 * evidence-hash stability, config lookups, posture overrides.
 */

import { test, expect, describe } from "bun:test";
import {
  assignModel,
  assignTools,
  applyPosture,
  canStartLeaf,
  emptyEvidence,
  evidenceHash,
  leafMachine,
  LEAF_TRANSITIONS,
  rollupChildState,
  runGates,
  transitionLeaf,
  StateMachine,
  type BranchState,
  type DependencyGraph,
  type Gate,
  type Leaf,
  type LeafEvidence,
  type LeafStatus,
  type TransitionGateCtx,
} from "./index";

// ── fixtures ──────────────────────────────────────────────────
function makeLeaf(id: string, status: LeafStatus = "pending"): Leaf {
  return {
    id,
    status,
    bottleneck: "standard",
    qa: "review",
    test: ["unit"],
    model: { provider: "deepseek", model: "deepseek-v4-flash", thinking: "off" },
    tools: ["agent-spec"],
    evidence: emptyEvidence(),
    reviewRounds: 0,
    trace: `branch/${id}`,
  };
}

function makeBranch(leaves: Leaf[] = []): BranchState {
  const leafMap: Record<string, Leaf> = {};
  for (const l of leaves) leafMap[l.id] = l;
  return {
    branchId: "test/branch",
    status: "in_progress",
    quality: "fast",
    leaves: leafMap,
    subBranches: [],
    childBranchStatus: {},
    transitions: [],
    integrationStatus: {
      reviewFileExists: false,
      healthCheckPassed: null,
      bombadilPassed: null,
      lonkeroPassed: null,
      allLeavesComplete: false,
      crossLeafConflicts: [],
    },
  };
}

// ── StateMachine legality ─────────────────────────────────────
describe("StateMachine legality", () => {
  test("legal forward path", () => {
    expect(leafMachine.canTransition("pending", "in_progress")).toBe(true);
    expect(leafMachine.canTransition("in_progress", "submitted")).toBe(true);
    expect(leafMachine.canTransition("submitted", "in_review")).toBe(true);
    expect(leafMachine.canTransition("in_review", "done")).toBe(true);
  });

  test("illegal skips blocked", () => {
    expect(leafMachine.canTransition("pending", "done")).toBe(false);
    expect(leafMachine.canTransition("pending", "in_review")).toBe(false);
    expect(leafMachine.canTransition("submitted", "done")).toBe(false);
  });

  test("wildcard → blocked from any state", () => {
    for (const s of leafMachine.states()) {
      expect(leafMachine.canTransition(s, "blocked")).toBe(true);
    }
  });

  test("revision loop in_review → in_progress", () => {
    expect(leafMachine.canTransition("in_review", "in_progress")).toBe(true);
  });

  test("contract revision escape hatch done → pending", () => {
    expect(leafMachine.canTransition("done", "pending")).toBe(true);
  });

  test("self-transition legal (idempotent)", () => {
    expect(leafMachine.canTransition("in_progress", "in_progress")).toBe(true);
  });

  test("blocked → in_progress only unblock", () => {
    expect(leafMachine.canTransition("blocked", "in_progress")).toBe(true);
    expect(leafMachine.canTransition("blocked", "done")).toBe(false);
  });

  test("done is terminal: done→done rejected (no silent mutation)", () => {
    expect(leafMachine.canTransition("done", "done")).toBe(false);
  });

  test("done escape hatch still legal (done→pending, done→blocked)", () => {
    expect(leafMachine.canTransition("done", "pending")).toBe(true);
    expect(leafMachine.canTransition("done", "blocked")).toBe(true);
  });

  test("states() enumerates all lifecycle states", () => {
    const states = leafMachine.states();
    expect(states).toContain("pending");
    expect(states).toContain("done");
    expect(states).toContain("blocked");
  });

  test("custom machine: empty table → only self-transitions", () => {
    const m = new StateMachine<string>([]);
    expect(m.canTransition("a", "a")).toBe(true);
    expect(m.canTransition("a", "b")).toBe(false);
  });
});

// ── transitionLeaf ────────────────────────────────────────────
describe("transitionLeaf", () => {
  test("applies legal transition + logs entry", () => {
    const branch = makeBranch([makeLeaf("a")]);
    const out = transitionLeaf(branch, {
      leafId: "a",
      to: "in_progress",
      now: () => "2026-01-01T00:00:00Z",
    });
    expect(out.transitioned).toBe(true);
    expect(out.result.pass).toBe(true);
    expect(out.state.leaves["a"].status).toBe("in_progress");
    expect(out.state.transitions).toHaveLength(1);
    expect(out.state.transitions[0]).toMatchObject({
      leaf: "a",
      from: "pending",
      to: "in_progress",
      timestamp: "2026-01-01T00:00:00Z",
    });
  });

  test("illegal transition rejected, no log", () => {
    const branch = makeBranch([makeLeaf("a")]);
    const out = transitionLeaf(branch, { leafId: "a", to: "done" });
    expect(out.transitioned).toBe(false);
    expect(out.result.pass).toBe(false);
    expect(out.result.reason).toMatch(/illegal/);
    expect(out.state.leaves["a"].status).toBe("pending");
    expect(out.state.transitions).toHaveLength(0);
  });

  test("unknown leaf rejected", () => {
    const out = transitionLeaf(makeBranch(), { leafId: "ghost", to: "in_progress" });
    expect(out.transitioned).toBe(false);
    expect(out.result.pass).toBe(false);
    expect(out.result.reason).toMatch(/not found/);
  });

  test("idempotent: replay same (to, evidence) with matching status → no-op pass", () => {
    let branch = makeBranch([makeLeaf("a")]);
    branch = transitionLeaf(branch, {
      leafId: "a",
      to: "in_progress",
      now: () => "2026-01-01T00:00:00Z",
    }).state;
    // replay: same target, same (empty) evidence hash, status already in_progress
    const out = transitionLeaf(branch, {
      leafId: "a",
      to: "in_progress",
      now: () => "2026-02-02T00:00:00Z",
    });
    expect(out.idempotentSkip).toBe(true);
    expect(out.transitioned).toBe(false);
    expect(out.result.pass).toBe(true);
    expect(out.state.transitions).toHaveLength(1); // no duplicate
  });

  test("NOT idempotent: new evidence → applies again", () => {
    let branch = makeBranch([makeLeaf("a")]);
    branch = transitionLeaf(branch, { leafId: "a", to: "in_progress" }).state;
    // different evidence → different hash → not a replay
    const out = transitionLeaf(branch, {
      leafId: "a",
      to: "in_progress",
      evidence: { agentSpecPassed: true },
    });
    expect(out.idempotentSkip).toBe(false);
    expect(out.transitioned).toBe(true);
  });

  test("gates: first block short-circuits", () => {
    const branch = makeBranch([makeLeaf("a")]);
    const blocking: Gate<TransitionGateCtx> = {
      name: "specExists",
      run: () => ({ pass: false, reason: "spec missing", severity: "block" }),
    };
    const out = transitionLeaf(branch, {
      leafId: "a",
      to: "in_progress",
      gates: [blocking],
    });
    expect(out.transitioned).toBe(false);
    expect(out.result.pass).toBe(false);
    expect(out.result.reason).toContain("specExists");
  });

  test("gates: warn severity does not block, surfaces in outcome", () => {
    const branch = makeBranch([makeLeaf("a")]);
    const warn: Gate<TransitionGateCtx> = {
      name: "estLOC",
      run: () => ({ pass: false, reason: "est 250 LOC", severity: "warn" }),
    };
    const out = transitionLeaf(branch, {
      leafId: "a",
      to: "in_progress",
      gates: [warn],
    });
    expect(out.transitioned).toBe(true);
    expect(out.result.pass).toBe(true);
    expect(out.result.severity).toBe("warn");
    expect(out.result.reason).toContain("estLOC");
  });

  test("evidence merged on transition", () => {
    const branch = makeBranch([makeLeaf("a", "in_progress")]);
    const out = transitionLeaf(branch, {
      leafId: "a",
      to: "submitted",
      evidence: { agentSpecPassed: true, npmTestPassed: true },
    });
    expect(out.transitioned).toBe(true);
    expect(out.state.leaves["a"].evidence.agentSpecPassed).toBe(true);
    expect(out.state.leaves["a"].evidence.npmTestPassed).toBe(true);
  });

  test("reviewRounds increments on revision loop only", () => {
    let branch = makeBranch([makeLeaf("a", "in_review")]);
    branch.leaves["a"].reviewRounds = 1;
    const out = transitionLeaf(branch, { leafId: "a", to: "in_progress" });
    expect(out.state.leaves["a"].reviewRounds).toBe(2);

    // pending → in_progress does NOT bump reviewRounds
    const branch2 = makeBranch([makeLeaf("b")]);
    const out2 = transitionLeaf(branch2, { leafId: "b", to: "in_progress" });
    expect(out2.state.leaves["b"].reviewRounds).toBe(0);
  });

  test("immutable: input state untouched", () => {
    const branch = makeBranch([makeLeaf("a")]);
    const snapshot = JSON.stringify(branch);
    transitionLeaf(branch, { leafId: "a", to: "in_progress" });
    expect(JSON.stringify(branch)).toBe(snapshot);
  });

  test("full lifecycle walks all 4 forward states", () => {
    let branch = makeBranch([makeLeaf("a")]);
    for (const to of ["in_progress", "submitted", "in_review", "done"] as LeafStatus[]) {
      branch = transitionLeaf(branch, { leafId: "a", to }).state;
      expect(branch.leaves["a"].status).toBe(to);
    }
    expect(branch.transitions).toHaveLength(4);
  });

  test("any state → blocked via transitionLeaf (WORKER_BLOCKER)", () => {
    const branch = makeBranch([makeLeaf("a", "in_progress")]);
    const out = transitionLeaf(branch, { leafId: "a", to: "blocked" });
    expect(out.transitioned).toBe(true);
    expect(out.state.leaves["a"].status).toBe("blocked");
  });

  test("blocked → in_progress via transitionLeaf (unblock)", () => {
    const branch = makeBranch([makeLeaf("a", "blocked")]);
    const out = transitionLeaf(branch, { leafId: "a", to: "in_progress" });
    expect(out.transitioned).toBe(true);
    expect(out.state.leaves["a"].status).toBe("in_progress");
  });

  test("done leaf rejects evidence mutation (done→done with new evidence)", () => {
    const branch = makeBranch([makeLeaf("a", "done")]);
    const out = transitionLeaf(branch, {
      leafId: "a",
      to: "done",
      evidence: { agentSpecPassed: true },
    });
    expect(out.transitioned).toBe(false);
    expect(out.result.pass).toBe(false);
    expect(out.state.leaves["a"].evidence.agentSpecPassed).toBe(false);
  });

  test("done leaf idempotent replay (same evidence) is safe no-op", () => {
    const base = makeBranch([makeLeaf("a", "done")]);
    const branch: BranchState = {
      ...base,
      transitions: [
        { leaf: "a", from: "in_review", to: "done", timestamp: "t", evidenceHash: evidenceHash(emptyEvidence()) },
      ],
    };
    const out = transitionLeaf(branch, { leafId: "a", to: "done" });
    expect(out.idempotentSkip).toBe(true);
    expect(out.result.pass).toBe(true);
  });
});

// ── evidenceHash ──────────────────────────────────────────────
describe("evidenceHash", () => {
  test("stable for same object", () => {
    expect(evidenceHash(emptyEvidence())).toBe(evidenceHash(emptyEvidence()));
  });

  test("key-order independent", () => {
    const a: LeafEvidence = { ...emptyEvidence(), agentSpecPassed: true, npmTestPassed: true };
    const b: LeafEvidence = { ...emptyEvidence(), npmTestPassed: true, agentSpecPassed: true };
    expect(evidenceHash(a)).toBe(evidenceHash(b));
  });

  test("changes when evidence changes", () => {
    const a = emptyEvidence();
    const b = { ...emptyEvidence(), agentSpecPassed: true };
    expect(evidenceHash(a)).not.toBe(evidenceHash(b));
  });

  test("array order matters (filesChanged)", () => {
    const a = { ...emptyEvidence(), filesChanged: ["x.ts", "y.ts"] };
    const b = { ...emptyEvidence(), filesChanged: ["y.ts", "x.ts"] };
    expect(evidenceHash(a)).not.toBe(evidenceHash(b));
  });
});

// ── runGates (chain helper) ───────────────────────────────────
describe("runGates", () => {
  const ctx = (leaf: Leaf): TransitionGateCtx => ({ leaf, evidence: leaf.evidence, to: "done" });

  test("all pass → pass", () => {
    const pass: Gate<TransitionGateCtx> = { name: "g", run: () => ({ pass: true }) };
    expect(runGates([pass], ctx(makeLeaf("a"))).pass).toBe(true);
  });

  test("block stops immediately", () => {
    const block: Gate<TransitionGateCtx> = { name: "b", run: () => ({ pass: false, reason: "x" }) };
    expect(runGates([block], ctx(makeLeaf("a")))).toMatchObject({ pass: false });
  });

  test("warnings collected, pass stays true", () => {
    const w: Gate<TransitionGateCtx> = {
      name: "w",
      run: () => ({ pass: false, reason: "soft", severity: "warn" }),
    };
    const r = runGates([w], ctx(makeLeaf("a")));
    expect(r.pass).toBe(true);
    expect(r.severity).toBe("warn");
    expect(r.reason).toContain("w");
  });
});

// ── canStartLeaf (dependency resolution) ──────────────────────
describe("canStartLeaf", () => {
  const graph: DependencyGraph = {
    nodes: ["a", "b", "c"],
    edges: [
      { from: "b", to: "a", kind: "needs" },
      { from: "c", to: "a", kind: "needs-contract" },
    ],
  };

  test("[needs:] blocks build+integrate until target done", () => {
    const leaves = { a: makeLeaf("a", "in_review"), b: makeLeaf("b"), c: makeLeaf("c") };
    let r = canStartLeaf("b", graph, leaves);
    expect(r.buildBlocked).toBe(true);
    expect(r.integrateBlocked).toBe(true);

    leaves["a"].status = "done";
    r = canStartLeaf("b", graph, leaves);
    expect(r.buildBlocked).toBe(false);
    expect(r.integrateBlocked).toBe(false);
  });

  test("[needs-contract:] build unblocks at in_review (not submitted), integrate at done", () => {
    const leaves: Record<string, Leaf> = { a: makeLeaf("a", "pending"), c: makeLeaf("c") };
    expect(canStartLeaf("c", graph, leaves).buildBlocked).toBe(true);

    // submitted is NOT enough — contract may be rejected in review
    leaves["a"].status = "submitted";
    expect(canStartLeaf("c", graph, leaves).buildBlocked).toBe(true);

    // in_review = contract reviewed & valid → build unblocks
    leaves["a"].status = "in_review";
    const r1 = canStartLeaf("c", graph, leaves);
    expect(r1.buildBlocked).toBe(false);
    expect(r1.integrateBlocked).toBe(true);

    leaves["a"].status = "done";
    const r2 = canStartLeaf("c", graph, leaves);
    expect(r2.buildBlocked).toBe(false);
    expect(r2.integrateBlocked).toBe(false);
  });

  test("leaf with no deps → fully unblocked", () => {
    const r = canStartLeaf("a", graph, { a: makeLeaf("a") });
    expect(r.buildBlocked).toBe(false);
    expect(r.integrateBlocked).toBe(false);
    expect(r.blockedBy).toHaveLength(0);
  });

  test("blocked target satisfies nothing", () => {
    const leaves = { a: makeLeaf("a", "blocked"), b: makeLeaf("b") };
    const r = canStartLeaf("b", graph, leaves);
    expect(r.buildBlocked).toBe(true);
    expect(r.blockedBy).toContain("a");
  });

  test("blockedBy lists contract vs runtime reasons", () => {
    const leaves = { a: makeLeaf("a", "pending"), c: makeLeaf("c") };
    const r = canStartLeaf("c", graph, leaves);
    expect(r.blockedBy.some((b) => b.includes("contract"))).toBe(true);
  });

  test("mixed [needs] + [needs-contract] edges", () => {
    const g: DependencyGraph = {
      nodes: ["x", "y", "z"],
      edges: [
        { from: "z", to: "x", kind: "needs" },
        { from: "z", to: "y", kind: "needs-contract" },
      ],
    };
    const leaves = { x: makeLeaf("x", "done"), y: makeLeaf("y", "in_review"), z: makeLeaf("z") };
    const r = canStartLeaf("z", g, leaves);
    expect(r.buildBlocked).toBe(false);
    expect(r.integrateBlocked).toBe(true); // y not done
  });

  test("ghost target defaults to pending → blocks", () => {
    const g: DependencyGraph = {
      nodes: ["b"],
      edges: [{ from: "b", to: "ghost", kind: "needs" }],
    };
    const r = canStartLeaf("b", g, { b: makeLeaf("b") });
    expect(r.buildBlocked).toBe(true);
    expect(r.blockedBy).toContain("ghost");
  });
});

// ── rollupChildState ──────────────────────────────────────────
describe("rollupChildState", () => {
  test("all complete", () => {
    const r = rollupChildState({ ui: "done", api: "done" });
    expect(r.allComplete).toBe(true);
    expect(r.anyBlocked).toBe(false);
    expect(r.inProgress).toHaveLength(0);
  });

  test("any blocked", () => {
    const r = rollupChildState({ ui: "done", api: "blocked" });
    expect(r.allComplete).toBe(false);
    expect(r.anyBlocked).toBe(true);
  });

  test("empty → not complete (no false success)", () => {
    expect(rollupChildState({}).allComplete).toBe(false);
  });

  test("in-progress children listed", () => {
    expect(rollupChildState({ ui: "in_progress" }).inProgress).toEqual(["ui"]);
  });
});

// ── config: assignModel ───────────────────────────────────────
describe("assignModel", () => {
  test("blocking bottleneck → strongest", () => {
    const m = assignModel("blocking", "full");
    expect(m.model).toBe("claude-sonnet-4");
    expect(m.thinking).toBe("max");
  });

  test("strict qa always strongest regardless of bottleneck", () => {
    const m = assignModel("standard", "strict");
    expect(m.model).toBe("claude-sonnet-4");
  });

  test("full qa bumps standard leaf to pro", () => {
    const m = assignModel("standard", "full");
    expect(m.model).toBe("deepseek-v4-pro");
    expect(m.thinking).toBe("high");
  });

  test("none qa + standard → cheapest flash", () => {
    const m = assignModel("standard", "none");
    expect(m.model).toBe("deepseek-v4-flash");
    expect(m.thinking).toBe("off");
  });

  test("e2e test → vision-capable model", () => {
    const m = assignModel("standard", "review", ["e2e"]);
    expect(m.provider).toBe("zai");
    expect(m.model).toBe("glm-5.2");
  });
});

// ── config: assignTools ───────────────────────────────────────
describe("assignTools", () => {
  test("always includes agent-spec", () => {
    expect(assignTools()).toContain("agent-spec");
  });

  test("unit test → test runner", () => {
    const t = assignTools(["unit"]);
    expect(t).toEqual(expect.arrayContaining(["vitest", "jest"]));
  });

  test("security domain → lonkero + tdd-guard", () => {
    const t = assignTools([], ["security"]);
    expect(t).toEqual(expect.arrayContaining(["lonkero", "tdd-guard"]));
  });

  test("dedupes across sources", () => {
    const t = assignTools(["unit", "snapshot"], ["web"]);
    expect(new Set(t).size).toBe(t.length);
    expect(t).toContain("tdd-guard");
  });
});

// ── config: applyPosture ──────────────────────────────────────
describe("applyPosture", () => {
  test("quality none → gates advisory only", () => {
    const o = applyPosture({
      phase: "production", compatibility: "compat", scope: "broad",
      quality: "none", budget: "balanced",
    });
    expect(o.enforceGates).toBe(false);
    expect(o.requireIntegrationReview).toBe(false);
  });

  test("prototype → no integration review required", () => {
    const o = applyPosture({
      phase: "prototype", compatibility: "break", scope: "broad",
      quality: "fast", budget: "balanced",
    });
    expect(o.enforceGates).toBe(true);
    expect(o.requireIntegrationReview).toBe(false);
    expect(o.maxReviewRounds).toBe(2);
  });

  test("production → full enforcement", () => {
    const o = applyPosture({
      phase: "production", compatibility: "compat", scope: "narrow",
      quality: "strict", budget: "generous",
    });
    expect(o.enforceGates).toBe(true);
    expect(o.requireIntegrationReview).toBe(true);
    expect(o.maxReviewRounds).toBe(5);
  });

  test("mvp + strict → integration review required", () => {
    const o = applyPosture({
      phase: "mvp", compatibility: "compat", scope: "broad",
      quality: "strict", budget: "balanced",
    });
    expect(o.requireIntegrationReview).toBe(true);
  });
});

